// ── Types ────────────────────────────────────────────────────────────────

export type AnalystSource =
  | { kind: "local"; tables: string[] } // empty tables = every local dataset
  | { kind: "warehouse"; connection_id: string };

export type AnalystCheckVerdict = "pass" | "refined" | "suspect";

/**
 * The predictive models an analyst may use — its own choice, made in the
 * same dialog as its reasoning model and its data. `null` (or absent) means
 * every model the owner can use; a list means exactly those, by name; an
 * empty list means none, and the planner is not told about scoring at all.
 * The same rule an agent's ML tool follows, enforced the same way: the
 * server refuses a model outside the list when a step tries to score with
 * it, whatever the planner was shown.
 */
export function analystModelsAllowed<T extends { name: string }>(
  models: T[],
  allow: readonly string[] | null | undefined,
): T[] {
  if (!Array.isArray(allow)) return models;
  const names = new Set(allow.map((n) => n.trim()).filter((n) => n.length > 0));
  return models.filter((m) => names.has(m.name));
}

/** What the analyst's card and dialog say about its predictive-model choice. */
export function describeModelChoice(
  allow: readonly string[] | null | undefined,
  total: number,
): string {
  if (!Array.isArray(allow)) {
    return total === 0 ? "No predictive models trained yet" : `Any predictive model (${total})`;
  }
  const n = allow.filter((s) => s.trim().length > 0).length;
  if (n === 0) return "No predictive models — steps are never scored";
  return `${n} of ${total} predictive model${total === 1 ? "" : "s"}`;
}

/**
 * Rank the SCORED rows by one of the model's output columns — the only way
 * to answer "the most / least / top N by the model": the output exists on
 * the scored rows and in no table, so no SQL can order by it. Measured
 * live: asked for the ten most anomalous orders, the SQL sampled fifty at
 * random, the reviewer tried `ORDER BY anomaly_score` and died on a binder
 * error, and the write-up reported the step as failed.
 */
export type ScoreRank = { by: string; desc: boolean; limit?: number };

export type AnalystStep = {
  goal: string;
  sql?: string;
  columns?: string[];
  /** Trimmed result sample (ANALYST_ROW_CAP rows) — the trace, not a store. */
  rows?: Record<string, unknown>[];
  /** True row count before trimming. */
  rowCount?: number;
  /**
   * This step's own visual.
   *
   * An analysis that ran three queries has three things to show; charting
   * only the headline threw the other two away and left the reader a table
   * of numbers to squint at. Every step whose result has a chartable SHAPE
   * gets its own chart — `{ type: "table" }` means the shape did not
   * support one, and the result table below it is the honest rendering.
   */
  chart?: ChartSpec;
  check?: { verdict: AnalystCheckVerdict; note: string };
  error?: string;
  /** The user edited this step's SQL and re-ran it (shown, and it matters). */
  edited?: boolean;
  /**
   * The governed query this step asked for, when the planner could express it
   * against a semantic model. Present means the SQL below was COMPILED from
   * the model's own definitions rather than written by the model.
   *
   * Until now governance was advisory: the definitions went into the prompt
   * with "never improvise a different formula" attached, and nothing checked
   * whether the SQL that came back obeyed. A metric that is authoritative
   * only when the model feels like it is not a governed metric.
   */
  semantic?: SemanticQuery;
  /** What the compile actually did — the disclosure half of `semantic`. */
  governed?: {
    model: string;
    /** A declared rollup answered instead of the fact table. Say which. */
    rollup?: string;
    /** Row filters / column masks the server applied for this viewer. */
    accessNote?: string;
  };
  /**
   * A what-if run of this step under changed assumptions.
   *
   * Kept BESIDE the measured result rather than replacing it, and never fed
   * into the findings: the write-up describes what was measured, and a
   * scenario that quietly joins it becomes a number nobody can tell from one.
   */
  scenario?: {
    changes: ScenarioChange[];
    label: string;
    sql: string;
    columns: string[];
    rows: Record<string, unknown>[];
    delta: MetricDelta[];
  };
  /**
   * The plan asked for this step's rows to be scored by a trained model.
   * Present means the SQL selects the entities and the model supplies the
   * prediction columns — the analyst never estimates a prediction itself.
   */
  score?: { model: string; rank?: ScoreRank };
  /**
   * The plan asked a trained FORECAST model for its projection. No SQL: the
   * rows are the model's periods with their interval, read through the same
   * runner the agent tool uses. Measured live: with forecast models hidden
   * from the planner, "what will monthly net_usd do over the next 3 months"
   * was answered by scoring fifty orders with a regression model and
   * inventing a flat monthly projection from their mean.
   */
  forecast?: { model: string; horizon?: number };
  /** What scoring actually did — the disclosure half of `score` (and of `forecast`). */
  scored?: ScoredDisclosure;
  status: "pending" | "writing_sql" | "running" | "scoring" | "checking" | "done" | "error";
};

/**
 * The governed fields a plan is allowed to name, flattened for validation.
 *
 * Kept as plain names rather than the full SemanticModel because the analyst
 * only needs to answer one question here — "does this model really have a
 * metric called that?" — and the full model lives on the server, which is
 * where the SQL is actually compiled.
 */
/**
 * A trained model the plan may score rows with — what the planner is told,
 * flattened like GovernedModelFields: names and columns, never the artifact.
 */
export type ScorableModel = {
  name: string;
  task: string;
  target: string | null;
  version: number | null;
  algorithm: string | null;
  /** One headline metric, named ("accuracy 0.94"), or null. */
  metric: string | null;
  /** Set when the model is bound to a feature view: rows are scored by key. */
  keyColumns: string[] | null;
  features: string[];
  /** The model's health line ("Health: …") — an open drift or decay alert, or what was last measured. */
  health: string | null;
};

/** What scoring actually did — the disclosure half of `score`. */
export type ScoredDisclosure = {
  model: string;
  version: number | null;
  task: string;
  algorithm: string | null;
  metric: string | null;
  /** True when the rows were scored by key through the model's feature view. */
  keys: boolean;
  featuresServedFrom: string | null;
  rowsScored: number;
  keysNotFound: string[];
  /**
   * The columns the model ADDED to the rows, as named on the table (after
   * any `predicted_` prefix) — so the self-check and the write-up can be
   * told which columns are estimates and which the SQL returned. Absent on
   * steps scored before it was recorded.
   */
  columns?: string[];
  /** The model's health line at scoring time, so the badge and the write-up can say it. */
  health: string | null;
  /**
   * What the tool said about the columns and the model — what the classes
   * mean, each group's profile, the trainer's warnings — minus the health
   * line, which is `health`. The write-up cannot describe a group it was
   * never told about.
   */
  notes?: string[];
  /** The ranking applied to the scored rows, when the plan asked for one. */
  ranked?: { by: string; desc: boolean; limit: number | null; of: number } | null;
  /** A forecast step: what one row is. */
  forecast?: {
    period: string | null;
    aggregation: string | null;
    lastObserved: string | null;
  } | null;
};

/** A forecast model's projection, as the loop receives it: one row per period. */
export type ForecastResult =
  | {
      ok: true;
      columns: string[];
      rows: Record<string, unknown>[];
      scored: ScoredDisclosure;
    }
  | { ok: false; error: string };

export type ScoreRowsResult =
  | {
      ok: true;
      columns: string[];
      rows: Record<string, unknown>[];
      scored: ScoredDisclosure;
    }
  | { ok: false; error: string };

/** Rows a scored step scores — the step's own sample, and the tool's cap. */
export const ANALYST_SCORE_CAP = 50;

/**
 * Join a model's predictions onto the rows they were made for.
 *
 * By KEY IDENTITY when the rows were scored through a feature view — the
 * tool carries the key column(s) on every prediction, and a prediction
 * attributed to the wrong entity is the worst failure this can have; by
 * position otherwise, since rows mode answers one prediction per input row
 * in order. A row with no prediction gets nulls, never a neighbour's values.
 *
 * A prediction column that COLLIDES with a column the SQL already returned
 * (a step that read a stored predictions table and then asked to score it)
 * is kept under a `predicted_` prefix rather than silently replaced or
 * silently dropped: the badge says a model scored these rows, so the model's
 * numbers must be the ones on the table.
 */
export function joinPredictions(
  rows: Record<string, unknown>[],
  predictions: Record<string, unknown>[],
  keyColumns: string[] | null,
): { columns: string[]; rows: Record<string, unknown>[]; added: string[] } {
  const inputColumns = rows.length ? Object.keys(rows[0]) : [];
  const keyed = !!keyColumns && keyColumns.length > 0;
  const print = (r: Record<string, unknown>) =>
    JSON.stringify((keyColumns ?? []).map((k) => String(r[k])));
  const predColumns: string[] = [];
  for (const p of predictions)
    for (const k of Object.keys(p))
      if (!(keyed && keyColumns!.includes(k)) && !predColumns.includes(k)) predColumns.push(k);
  const outName = (c: string) => (inputColumns.includes(c) ? `predicted_${c}` : c);
  const byPrint = keyed ? new Map(predictions.map((p) => [print(p), p])) : null;
  const joined = rows.map((r, i) => {
    const p = byPrint ? byPrint.get(print(r)) : predictions[i];
    const out: Record<string, unknown> = { ...r };
    for (const c of predColumns) out[outName(c)] = p ? (p[c] ?? null) : null;
    return out;
  });
  const added = predColumns.map(outName);
  return { columns: [...inputColumns, ...added], rows: joined, added };
}

const escapeRx = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/** True when `name` appears whole in `text` (case-insensitive, not inside another word). */
export function namesModel(text: string, name: string): boolean {
  return new RegExp(`(^|[^\\w])${escapeRx(name)}([^\\w]|$)`, "i").test(text);
}

/**
 * Rank scored rows by a model output column, nulls last, then keep the top
 * `limit`. A column the rows do not have leaves them unranked and SAYS so —
 * an unranked table presented as "the ten most anomalous" is the lie this
 * exists to prevent.
 */
export function rankScoredRows(
  rows: Record<string, unknown>[],
  rank: ScoreRank,
  columns: string[],
): {
  rows: Record<string, unknown>[];
  applied: { by: string; desc: boolean; limit: number | null; of: number } | null;
  note: string | null;
} {
  if (!columns.includes(rank.by)) {
    return {
      rows,
      applied: null,
      note:
        `The plan asked to rank by "${rank.by}", which is not a column of the scored rows ` +
        `(${columns.join(", ")}); the rows below are unranked.`,
    };
  }
  const dir = rank.desc ? -1 : 1;
  const sorted = [...rows].sort((a, b) => {
    const x = a[rank.by];
    const y = b[rank.by];
    const xn = x === null || x === undefined;
    const yn = y === null || y === undefined;
    if (xn || yn) return xn && yn ? 0 : xn ? 1 : -1;
    if (typeof x === "number" && typeof y === "number") return (x - y) * dir;
    return String(x).localeCompare(String(y)) * dir;
  });
  const limit = rank.limit && rank.limit > 0 ? Math.floor(rank.limit) : null;
  return {
    rows: limit ? sorted.slice(0, limit) : sorted,
    applied: { by: rank.by, desc: rank.desc, limit, of: rows.length },
    note: null,
  };
}

const GENERIC_MODEL_WORDS = new Set([
  "same",
  "this",
  "that",
  "trained",
  "ml",
  "machine",
  "learning",
  "data",
  "semantic",
  "governed",
  "best",
  "right",
  "new",
  "other",
  "any",
  "a",
  "an",
  "the",
  "forecast",
  "forecasting",
  "prediction",
  "predictive",
  "scoring",
  "regression",
  "classification",
  "classifier",
  "clustering",
  "anomaly",
  "recommendation",
  "selected",
  "chosen",
  "current",
  "appropriate",
  "suitable",
  "available",
  "existing",
  "fitting",
  "registry",
]);

/**
 * The model a question names that does not exist — "the churn model" when
 * there is none. Measured live: the planner silently scored the rows with
 * the clustering model instead and the write-up presented "top five at
 * risk". Returns the phrase to ask about, or null when every named word
 * belongs to a known model (or the words are generic — "a trained forecast
 * model" names a kind, not a model). What to do about it is the loop's
 * call: ask, or — once the user has chosen to go on without the model —
 * strip a plan that still reaches for another one.
 */
export function namedModelMissing(question: string, known: string[]): string | null {
  // The words between the LAST determiner and "model": "the customers with
  // the churn model" names "churn", not "customers with the churn".
  const m = question.match(
    /\b(?:the|a|an|our|my|your)\s+((?:(?!(?:the|a|an|our|my|your)\s)[A-Za-z0-9_\u00b7-]+\s+){1,5}?)model\b/i,
  );
  if (!m) return null;
  const phrase = m[1].trim();
  const words = phrase
    .toLowerCase()
    .split(/[\s\u00b7-]+/)
    .filter((w) => w && !GENERIC_MODEL_WORDS.has(w));
  if (words.length === 0) return null;
  const lower = known.map((n) => n.toLowerCase());
  const hit = lower.some((n) => words.every((w) => n.includes(w)));
  return hit ? null : phrase;
}

export type GovernedModelFields = {
  name: string;
  label?: string;
  table: string;
  metrics: string[];
  dimensions: string[];
  timeDimensions: string[];
  /** Declared assumptions a what-if scenario may vary. */
  parameters?: ScenarioParameter[];
};

export type AnalystTurn = {
  question: string;
  /** The analyst's stated approach — shown before any query runs. */
  approach?: string;
  steps: AnalystStep[];
  /** Final synthesis, markdown. */
  answer?: string;
  /** The LEAD visual's step — the one that best answers the question. */
  chartStep?: number;
  /** Questions this analysis makes worth asking next. */
  followUps?: string[];
  /**
   * The analyst stopped BEFORE querying to ask something it could not
   * sensibly decide. The assumption is what it would proceed with, so the
   * user can accept it in one click instead of retyping the question.
   */
  clarify?: string;
  assumption?: string;
  /**
   * The findings predate the step results below them, because a step was
   * edited and re-run after they were written. Shown as a warning until the
   * user rewrites them — silently keeping stale prose next to fresh numbers
   * is the exact dishonesty this feature exists to avoid.
   */
  answerStale?: boolean;
  /**
   * A human's verdict on this analysis, pinned to the steps it was given.
   *
   * See analystVerification: the fingerprint is what stops a green tick
   * outliving the SQL it vouched for. An unverified answer is read with
   * ordinary caution; a falsely verified one is read with none.
   */
  verification?: TurnVerification;
  status: "planning" | "working" | "checking" | "synthesizing" | "done" | "clarifying" | "error";
  error?: string;
  at?: string;
  /**
   * The model that produced THIS turn, stamped when it ran.
   *
   * An analyst's model can be changed after the fact, and without this the
   * report header reads the analyst's CURRENT model and attributes every
   * older analysis to a model that never saw the question. Absent on turns
   * recorded before analysts were editable — those necessarily ran on the
   * analyst's model of the day, so falling back to it is accurate for them
   * and only for them.
   */
  model?: string;
};

/**
 * What to print as the model behind a set of turns.
 *
 * Several models can appear in one thread once the analyst is edited
 * mid-conversation, and naming just one of them would be a guess. Turns
 * with no stamp fall back to `current` — see AnalystTurn.model for why that
 * is sound for exactly those turns.
 */
/**
 * What an analyst should be called after its data source changes.
 *
 * A name the user typed is theirs and survives. A name they never touched is
 * one WE derived from the old source, so leaving it alone would let an
 * analyst go on describing data it no longer reads — "Snowflake · sales"
 * pointing at a local upload. Compared against the auto-name of the OLD
 * source, which is the only way to tell the two cases apart after the fact.
 */
export function analystNameOnEdit(args: {
  currentName: string;
  autoNameForOldSource: string;
  autoNameForNewSource: string;
}): string {
  return args.currentName.trim() === args.autoNameForOldSource.trim()
    ? args.autoNameForNewSource
    : args.currentName;
}

export function modelsUsedIn(turns: AnalystTurn[], current: string): string {
  const names = new Set<string>();
  for (const t of turns ?? []) names.add((t.model ?? current).split("::").pop() ?? current);
  const list = [...names].filter(Boolean);
  if (list.length === 0) return current.split("::").pop() ?? current;
  if (list.length <= 2) return list.join(" + ");
  return `${list[0]} + ${list.length - 1} more`;
}

// ── Limits ───────────────────────────────────────────────────────────────

/** Most questions decompose into 2–3 queries; more is a sign of drift. */
export const MAX_ANALYSIS_STEPS = 4;

/** Rows kept per step in the stored trace (same discipline as widgets). */
export const ANALYST_ROW_CAP = 50;

/**
 * Did this step's query return more rows than the trace keeps?
 *
 * Only answerable when the query returned its REAL result — a defensive
 * LIMIT in the SQL makes the truncation invisible to everyone downstream,
 * which is why the SQL prompt now forbids one. Measured before this
 * existed: a heatmap pull came back as exactly "50 rows" with no
 * disclosure anywhere, because the LIMIT hid the other 58.
 */
export function isCapTruncated(step: Pick<AnalystStep, "rowCount" | "rows">): boolean {
  return (step.rowCount ?? 0) > (step.rows?.length ?? 0) || (step.rowCount ?? 0) > ANALYST_ROW_CAP;
}

/** Prior Q/A pairs carried into the next question's context. */
export const ANALYST_MEMORY_TURNS = 4;

/** Follow-up questions offered after an answer. Three fit; six is a menu. */
export const MAX_FOLLOW_UPS = 3;

/**
 * Completion budgets, sized for REASONING models — which is what this
 * feature tells you to pick.
 *
 * A reasoning model's thinking tokens are charged against the completion
 * cap, so a budget sized for the visible answer starves the invisible part
 * and the model returns nothing at all. Measured: gpt-5-mini, planning a
 * three-part discount question with a 1,200 cap, spent 1,152 completion
 * tokens and returned `{}` — 25 seconds, real money, and a user-facing
 * "returned no analysis steps". These are deliberately generous; the plan
 * and check replies are small, so the headroom is spent on thinking, not on
 * output nobody reads.
 */
export const ANALYST_TOKENS = { plan: 6000, check: 8000, synthesis: 8000 } as const;

// ── Reasoning-model heuristic (the create dialog's nudge) ────────────────

// Families marketed and benchmarked as reasoning/thinking models. The
// dialog SUGGESTS one of these; it never blocks — the list is a heuristic
// over provider ids, not a gate, and new model names appear monthly.
const REASONING_MODEL_RE =
  /(^|[/:.-])o[134](\b|-)|gpt-5|deepseek-r1|\bqwq\b|thinking|reasoner|reasoning|claude-(fable|mythos|opus)|(opus|sonnet)-[45]|claude-[45]|gemini-[23][.-]5-pro|grok-[34]/i;

export function isReasoningModelId(id: string): boolean {
  return REASONING_MODEL_RE.test(id);
}

// ── Pure helpers ─────────────────────────────────────────────────────────

/** SELECT/WITH only, one statement — applied to every SQL before it runs. */
export function assertSelectOnly(sql: string): string {
  const s = sql.trim().replace(/;\s*$/, "");
  if (!/^(select|with)\b/i.test(s)) {
    throw new Error("The analyst may only run SELECT statements.");
  }
  if (s.includes(";")) {
    throw new Error("The analyst may only run a single statement.");
  }
  return s;
}

/**
 * Cap a step's stored rows; everything else in the trace is kept.
 *
 * The true count is recorded before the slice — without it the UI's
 * "(showing 50)" disclosure has nothing to disclose, and a trimmed step
 * would claim its sample as the whole result. That is the exact defect the
 * ANALYST_ROW_CAP machinery exists to prevent.
 */
export function trimStepForStorage(step: AnalystStep): AnalystStep {
  if (!step.rows || step.rows.length <= ANALYST_ROW_CAP) return step;
  return {
    ...step,
    rowCount: step.rowCount ?? step.rows.length,
    rows: step.rows.slice(0, ANALYST_ROW_CAP),
  };
}

export function trimTurnForStorage(turn: AnalystTurn): AnalystTurn {
  return { ...turn, steps: turn.steps.map(trimStepForStorage) };
}

/**
 * A turn as an ANONYMOUS embed visitor may receive it.
 *
 * The signed-in screen shows each step's SQL because the reader owns the data
 * and re-running it is the point. On a public embed that same field publishes
 * internal table and column names — `FROM hr_dept_monthly` names a table
 * nobody outside the company should learn from a chat widget. This is the
 * same reason sanitizePublicWidgets allow-lists render fields for embedded
 * dashboards, and it is enforced HERE rather than by the page declining to
 * render it: a field that reaches the browser has been published, whatever
 * the UI does with it.
 *
 * `governed` survives deliberately. It names the semantic model the step
 * compiled against, which the owner chose to define and which is the reader's
 * evidence that a number came from a governed definition rather than
 * improvised SQL — a trust signal, not a schema leak.
 */
export function sanitizePublicTurn(turn: AnalystTurn): AnalystTurn {
  return {
    ...turn,
    steps: turn.steps.map((s) => {
      const { sql: _sql, semantic: _semantic, ...safe } = s;
      return safe;
    }),
  };
}

/** Compact Q→A lines from prior turns, for conversational continuity. */
export function priorContext(turns: AnalystTurn[], max = ANALYST_MEMORY_TURNS): string {
  const done = turns.filter((t) => t.status === "done" && t.answer);
  const recent = done.slice(-max);
  if (recent.length === 0) return "";
  const lines = recent.map(
    (t) => `Q: ${t.question}\nA: ${(t.answer ?? "").slice(0, 500).replace(/\s+/g, " ")}`,
  );
  return `EARLIER IN THIS ANALYSIS:\n${lines.join("\n")}\n`;
}

// ── Prompts (pure, exported so tests read what the app actually sends) ───

/**
 * The governed vocabulary, written out so the plan can NAME it exactly.
 *
 * `describeSchema` already shows governed metrics as expressions, which tells
 * the model what they mean. This tells it what they are CALLED, which is the
 * part it has to get exactly right for the compiler to accept the block.
 */
export function describeGovernedVocabulary(catalog: GovernedModelFields[]): string {
  if (catalog.length === 0) return "";
  const lines = catalog.slice(0, 8).map((m) => {
    const met = m.metrics.slice(0, 24).join(", ");
    const dim = m.dimensions.slice(0, 24).join(", ");
    const time = m.timeDimensions.length
      ? `\n  time dimensions: ${m.timeDimensions.join(", ")}`
      : "";
    return `MODEL ${m.name}${m.label ? ` (${m.label})` : ""} over ${m.table}\n  metrics: ${met}\n  dimensions: ${dim}${time}`;
  });
  return (
    "\n\nGOVERNED MODELS YOU CAN COMPILE AGAINST (preferred — these definitions are " +
    "authoritative and the SQL is generated from them, not by you):\n" +
    lines.join("\n")
  );
}

/**
 * The trained models a plan may score rows with, for the planner.
 *
 * Only present when a model is in scope — the same cost discipline as the
 * governed vocabulary — and phrased as what a step must RETURN for scoring
 * to work: the key column(s) when the model has a feature view (the
 * features are then read from the view, which is the whole point of one),
 * else the feature columns themselves.
 */
/** The columns a model of this task adds to a scored row — the vocabulary a plan may rank by. */
export function modelOutputs(task: string): string {
  switch (task) {
    case "classification":
      return "prediction (the class), probability (confidence in it), proba_<class> (each class's probability)";
    case "regression":
      return "prediction (the estimated value)";
    case "anomaly":
      return "prediction (1 = anomaly), anomaly_score (higher = more unusual)";
    case "clustering":
      return "prediction (the group number), distance (smaller = more typical of the group)";
    case "recommendation":
      return "prediction (ranked items), scores, cold_start";
    default:
      return "prediction";
  }
}

export function describeScorableModels(models: ScorableModel[]): string {
  const scorable = models.filter((m) => m.task !== "forecast");
  const forecasters = models.filter((m) => m.task === "forecast");
  if (scorable.length === 0 && forecasters.length === 0) return "";
  const forecastBlock =
    forecasters.length === 0
      ? ""
      : "\n\nFORECAST MODELS (a projection of the series each was trained on — the step needs NO " +
        "SQL; the platform returns the model's projected periods with an interval):\n" +
        forecasters
          .slice(0, 8)
          .map(
            (m) =>
              `MODEL ${m.name} — forecast` +
              (m.target ? ` → ${m.target}` : "") +
              (m.version !== null ? `, v${m.version}` : "") +
              (m.metric ? `, ${m.metric}` : "") +
              (m.health ? `\n  ${m.health}` : ""),
          )
          .join("\n");
  if (scorable.length === 0) return forecastBlock;
  const lines = scorable.slice(0, 8).map((m) => {
    const by = m.keyColumns
      ? `score by key — the step's SQL must return ${m.keyColumns.map((k) => `"${k}"`).join(" and ")}; the features are read from the model's feature view`
      : `the step's SQL must return the feature columns: ${m.features.slice(0, 24).join(", ")}`;
    const head =
      `MODEL ${m.name} — ${m.task}` +
      (m.target ? ` → ${m.target}` : "") +
      (m.version !== null ? `, v${m.version}` : "") +
      (m.metric ? `, ${m.metric}` : "");
    // The owner's warning, where the planner decides whether to lean on it.
    const health = m.health ? `\n  ${m.health}` : "";
    return `${head}\n  ${by}\n  outputs: ${modelOutputs(m.task)}${health}`;
  });
  return (
    "\n\nTRAINED MODELS YOU CAN SCORE ROWS WITH (a prediction per row — an estimate, " +
    "never an observed value):\n" +
    lines.join("\n") +
    forecastBlock
  );
}

/**
 * What the SQL writer must know about a scored step.
 *
 * The planner is told what a scored step must return; the SQL is written in
 * a SEPARATE call that sees only the step's goal — so the rule never reached
 * the writer, and live it reached for a stored predictions table it found in
 * the schema, twice, returning the columns the model would have produced
 * instead of the entities the model was to score. The goal now carries the
 * requirement into the writer's prompt.
 */
export function scoringSqlGoal(
  step: Pick<AnalystStep, "goal" | "score">,
  models: ScorableModel[] = [],
): string {
  if (!step.score) return step.goal;
  const m = models.find((x) => x.name === step.score?.model);
  const need = m?.keyColumns?.length
    ? `the column(s) ${m.keyColumns.map((k) => `"${k}"`).join(" and ")} of the entities to score, one row per DISTINCT entity`
    : m
      ? `one row per DISTINCT entity to score with the feature columns ${m.features.slice(0, 24).join(", ")}, plus the column(s) that identify the entity (its id or name) so the scored rows can be named`
      : "one row per DISTINCT entity to score";
  return (
    `${step.goal}. The rows this query returns will be scored by the trained model ` +
    `"${step.score.model}" AFTER the query runs: return ${need} — ` +
    (step.score.rank
      ? `up to 50 rows (the platform keeps the top ${step.score.rank.limit ?? "N"} by ${step.score.rank.by} after scoring, so do NOT limit to that number) — `
      : `at most 50 rows, or the number the goal itself names — `) +
    `from the source table itself: do NOT read any stored ` +
    `predictions table, do NOT compute a prediction yourself, and never ORDER BY or filter on ` +
    `a model output (it exists in no table; the platform ranks the scored rows).`
  );
}

export function buildAnalysisPlanPrompt(args: {
  schema: string;
  question: string;
  prior: string;
  /** Governed models in scope; empty means the plan cannot claim governance. */
  catalog?: GovernedModelFields[];
  /** Trained models in scope; empty means no step can be scored. */
  models?: ScorableModel[];
}): { systemPrompt: string; userPrompt: string } {
  const vocabulary = describeGovernedVocabulary(args.catalog ?? []);
  const scorable = describeScorableModels(args.models ?? []);
  const hasForecasters = (args.models ?? []).some((m) => m.task === "forecast");
  // The user accepted the analyst's assumption (the route re-asks with it
  // appended). Measured live: the planner asked the same question again.
  const answeredRule = /Proceed with this assumption:/.test(args.question)
    ? '\n\nTHE USER HAS ANSWERED. The question ends with "Proceed with this assumption: …" — ' +
      "that is the answer to whatever you would have asked. Plan under that assumption; do " +
      "NOT return clarify again."
    : "";
  const scoreRule = scorable
    ? "\n\nADD A SCORED STEP when the question asks which rows are LIKELY something, for a " +
      "predicted value, or to estimate, score or predict with a NAMED trained model: add " +
      '"score": { "model": "<model name>" } to that step. Its SQL must return one row per ' +
      "entity to score — the model's key column(s) when it scores by key, else its feature " +
      "columns — and at most fifty rows. Use the EXACT model name; a step naming any other " +
      "model loses its scoring. Never estimate a prediction yourself: a scored step is the " +
      "only way to get one, and a step without one holds observed values only. " +
      "For the MOST / LEAST / TOP-N BY THE MODEL'S OUTPUT (most anomalous, most likely " +
      'enterprise, highest predicted value) add "rank": { "by": "<output column>", "desc": ' +
      'true, "limit": N } inside "score": the SQL still returns a sample of entities (at most ' +
      "fifty) and the platform ranks the scored rows — a model output exists in no table, so " +
      "SQL can never sort or filter by it. A regression model estimates one row at a time; it " +
      "is NOT a forecast." +
      (hasForecasters
        ? " ADD A FORECAST STEP when the question asks what a series WILL do over coming " +
          'periods: add "forecast": { "model": "<forecast model name>", "horizon": N } with no ' +
          "other work in that step — the platform returns the model's projected periods. " +
          "Never use a regression model to forecast."
        : "") +
      " If the question names a model that is not listed, do not substitute another model: " +
      'return { "clarify": ... } saying no model of that name exists and naming the ones that do.'
    : "";
  const governedRule = vocabulary
    ? "\n\nPREFER A GOVERNED STEP when the step's numbers come from a governed model's " +
      'metrics. Add "semantic": { "model": "<model name>", "metrics": ["<metric>"], ' +
      '"dimensions": ["<dimension>"], "grains": { "<time dimension>": "month" }, ' +
      '"filters": [{ "field": "<field>", "op": "=", "value": "..." }], ' +
      '"orderBy": [{ "field": "<metric or dimension>", "dir": "desc" }], "limit": 100 } ' +
      "to that step. ALWAYS give orderBy when the step asks for a top/bottom N — a limit " +
      "without an ordering returns arbitrary rows. " +
      "Use the EXACT names listed — every name is checked against the model, " +
      "and a step naming anything else silently loses its governed status and falls back to " +
      "hand-written SQL. Omit `semantic` for steps a governed model cannot express."
    : "";
  return {
    systemPrompt:
      "You are a senior data analyst planning an analysis. Decompose the question into the " +
      `SMALLEST set of concrete SQL-answerable steps (1-${MAX_ANALYSIS_STEPS}) over the ` +
      "provided schema. Each step is one query's worth of work with a measurable goal — " +
      '"total sales by region", not "explore the data". Prefer ONE step when one query ' +
      "answers the question; add steps only when the answer genuinely needs several angles " +
      "(a total plus a breakdown, a trend plus its outliers, a comparison of two segments). " +
      "Only use tables and columns that exist in the schema. Do not write SQL here.\n\n" +
      // A guess that runs is worse than a question that doesn't: a wrong
      // assumption comes back as confident numbers nobody can see the
      // assumption behind. Measured: "…this quarter" ran against a quarter
      // with no rows and reported an empty breakdown as the answer.
      "ASK BEFORE GUESSING, but only when the question cannot be answered WELL without an " +
      'answer: an unstated time range on a time-sensitive question, a word ("churn", "active") ' +
      "the schema defines two plausible ways, or a metric the schema does not have under any " +
      "name. Do NOT ask about things you can decide sensibly yourself — sort order, chart type, " +
      "row limits, which of two equivalent columns to group by. When you must ask, return " +
      '{ "clarify": "one specific question", "assumption": "what you would assume if told to ' +
      'proceed" } and NOTHING else.' +
      governedRule +
      scoreRule +
      answeredRule,
    userPrompt:
      `${args.schema}${vocabulary}${scorable}\n\n${args.prior}QUESTION: ${args.question}\n\n` +
      `Return JSON: { "approach": "1-3 sentences on how you'll answer and why these steps", ` +
      `"steps": [ { "goal": "concrete, measurable step goal"${
        vocabulary ? ', "semantic": { ... } (optional)' : ""
      }${
        scorable
          ? ', "score": { "model": "<model name>", "rank": { "by": "<output column>", "desc": true, "limit": N } } (optional; rank optional)' +
            (hasForecasters
              ? ', "forecast": { "model": "<forecast model name>", "horizon": N } (optional)'
              : "")
          : ""
      } } ] } ` +
      `— OR { "clarify": "...", "assumption": "..." } if you genuinely cannot proceed well.`,
  };
}

export function buildCheckPrompt(args: {
  question: string;
  steps: Array<{
    goal: string;
    sql?: string;
    facts: string;
    error?: string;
    /** A trained model scored this step's rows after the SQL ran; these are the columns it added. */
    scored?: { model: string; columns: string[]; ranked?: string | null };
    /** A forecast model's projection — there is no SQL to correct. */
    forecast?: {
      model: string;
      period?: string | null;
      periods?: number;
      lastObserved?: string | null;
    };
  }>;
  /** Governed models in scope — named so the reviewer cannot mistake one for a table. */
  catalog?: GovernedModelFields[];
}): { systemPrompt: string; userPrompt: string } {
  // A scored step's facts carry the model's columns beside the SQL's, and
  // nothing said which was which. Measured live: the reviewer "corrected"
  // a scored step with `SELECT order_id, prediction, probability, …` and
  // the rewrite died on `Binder Error: Referenced column "prediction" not
  // found` — the prediction exists in no table; the model wrote it onto the
  // rows after the query. The reviewer is now told which columns are the
  // model's, that they are not in any table, and that a correction returns
  // the same key column(s) and is scored again on its own.
  const scoredRule = args.steps.some((s) => s.scored || s.forecast)
    ? "\n\nA STEP MARKED SCORED AFTER THE QUERY had its rows scored by a trained model once " +
      "the SQL had run. Judge only whether the SQL returned the right rows to score — the " +
      "entities its goal names — and never the predictions themselves: the model's columns " +
      "exist in no table, so a refined_sql must not select, filter or sort by them; it " +
      "returns the same key column(s) from the source table, and its rows are scored again " +
      "automatically. A ranking by a model output (RANKED BY) was applied by the platform " +
      "after scoring — never propose ORDER BY on one. A step marked FORECAST BY has no SQL: " +
      "its rows are the model's projected periods; judge only whether that answers the goal. " +
      "A step whose goal names a trained model but is NOT marked SCORED AFTER THE QUERY or " +
      "FORECAST BY did not run it: its numbers are observed values, so mark it suspect and " +
      "say the model did not run."
    : "";
  // A step that FELL BACK to hand-written SQL still carries a goal phrased
  // around the governed model ("From saas_sales_model, compute total_sales…").
  // Measured live: the reviewer read that as a table name, "corrected" correct
  // SQL to `FROM saas_sales_model`, and the rewrite died on
  // `Catalog Error: Table with name saas_sales_model does not exist!`. The
  // original result survived and the step was flagged, so nothing wrong was
  // shown — but the concern raised was fictional, and a reviewer that cries
  // wolf is a reviewer people stop reading.
  const modelsAreNotTables = (args.catalog ?? []).length
    ? "\n\nGOVERNED MODELS ARE NOT TABLES. " +
      (args.catalog ?? [])
        .map((m) => `"${m.name}" is a semantic model over the table ${m.table}`)
        .join("; ") +
      ". A step's goal may name a model; the SQL must still select FROM the underlying " +
      "table. Never rewrite a query to select from a model name."
    : "";
  const stepBlocks = args.steps
    .map(
      (s, i) =>
        `STEP ${i + 1}: ${s.goal}\nSQL: ${s.sql ?? "(none)"}\n` +
        (s.scored
          ? `SCORED AFTER THE QUERY by the trained model "${s.scored.model}": the column(s) ` +
            `${s.scored.columns.join(", ")} are the model's estimates, added to the rows after ` +
            `the SQL ran — they exist in no table.${s.scored.ranked ? ` RANKED BY ${s.scored.ranked}.` : ""}\n`
          : "") +
        (s.forecast
          ? `FORECAST BY the trained model "${s.forecast.model}": the rows are its projected ` +
            `periods (period, forecast, lower, upper)` +
            (s.forecast.periods
              ? ` — ${s.forecast.periods} of them, each one ${s.forecast.period ?? "period"}` +
                (s.forecast.lastObserved ? `, after ${s.forecast.lastObserved}` : "")
              : "") +
            `; there is no SQL to correct. If the goal asks for a different period (months when ` +
            `each row is a week) or a different horizon, say so in the note.\n`
          : "") +
        (s.error ? `ENGINE ERROR: ${s.error}` : `RESULT FACTS: ${s.facts}`),
    )
    .join("\n\n");
  return {
    systemPrompt:
      "You are the same analyst REVIEWING YOUR OWN WORK before presenting it. For each step, " +
      "judge whether its result actually answers its goal: empty results for questions that " +
      "should have data, totals of the wrong magnitude, groupings split by case variants, a " +
      "LIMIT that cut a ranking short, nulls sorted to the top, the wrong column. " +
      'Verdicts: "pass" (result answers the goal), "suspect" (present the result but flag ' +
      'the concern in the note). If a step is WRONG and you can fix it, return "refined_sql" ' +
      "with a corrected single SELECT statement — it will be re-executed and replace the " +
      "result. Be specific in notes: name the number or shape that concerns you. Never " +
      "invent data." +
      modelsAreNotTables +
      scoredRule,
    userPrompt:
      `QUESTION: ${args.question}\n\n${stepBlocks}\n\n` +
      `Return JSON: { "checks": [ { "verdict": "pass|suspect", "note": "one sentence", ` +
      `"refined_sql": "SELECT ... (only when correcting)" } ], ` +
      `"headline": <index of the step whose result best answers the question, 0-based> }`,
  };
}

export function buildSynthesisPrompt(args: {
  question: string;
  approach: string;
  prior: string;
  steps: Array<{
    goal: string;
    facts: string;
    verdict?: string;
    note?: string;
    error?: string;
    /** "model vN (metric)" when a trained model scored this step's rows. */
    scored?: string;
    /** The step is a forecast model's projection, not a scored query. */
    forecast?: boolean;
    /** What the tool said about the model's columns — class meanings, group profiles, warnings. */
    scoredNotes?: string[];
  }>;
}): { systemPrompt: string; userPrompt: string } {
  const stepBlocks = args.steps
    .map(
      (s, i) =>
        `STEP ${i + 1}: ${s.goal}\n` +
        (s.error
          ? `FAILED: ${s.error}`
          : `RESULT: ${s.facts}${
              s.scored
                ? s.forecast
                  ? `\nFORECAST BY: ${s.scored} — the rows are the model's projected periods with an interval`
                  : `\nSCORED BY: ${s.scored} — the prediction columns are model estimates`
                : ""
            }${
              s.scoredNotes && s.scoredNotes.length
                ? `\nMODEL NOTES:\n${s.scoredNotes.map((n) => `- ${n}`).join("\n")}`
                : ""
            }${s.verdict ? `\nCHECK: ${s.verdict}${s.note ? ` — ${s.note}` : ""}` : ""}`),
    )
    .join("\n\n");
  const anyScored = args.steps.some((s) => s.scored);
  return {
    systemPrompt:
      "You are a senior data analyst writing up findings. Answer the question using ONLY the " +
      "step results below — every number in your answer must appear in a step result, cited " +
      "like (step 2). Lead with the direct answer, then the supporting evidence, then any " +
      "caveat a careful analyst would add (suspect checks, failed steps, sample caps). " +
      "Markdown, short paragraphs and lists, no headings. If the steps do not answer the " +
      "question, say exactly what is missing instead of guessing." +
      // The same honesty rule the forecaster carries: a prediction is what a
      // model expects, and a write-up that says "will" where the data says
      // "is likely to" has turned an estimate into a fact.
      (anyScored
        ? " A step marked SCORED BY carries PREDICTIONS from a trained model: report them as " +
          "what the model estimates or expects, name the model where you cite them, and never " +
          "present a predicted value as something that was observed. Use its MODEL NOTES to " +
          "explain what a class, a group or a score means. A SCORED BY regression step gives " +
          "one estimate per row and is not a series — never turn it into a projection. A step " +
          "marked FORECAST BY holds the model's projected periods with an interval: report them " +
          "as what the model expects, with the interval."
        : "") +
      " A step NOT marked SCORED BY or FORECAST BY holds observed values only — never call " +
      "its numbers a model's estimate or forecast. A CHECK note saying a proposed correction " +
      "failed or was refused means the step's own result above stands: the step did not fail, " +
      "report its numbers.",
    userPrompt:
      `${args.prior}QUESTION: ${args.question}\nAPPROACH: ${args.approach}\n\n${stepBlocks}\n\n` +
      `Return JSON: { "answer": "markdown", "follow_ups": ` +
      `["up to ${MAX_FOLLOW_UPS} short questions THIS analysis makes worth asking next — ` +
      `each answerable from the same data, each a real next step rather than a restatement"] }`,
  };
}

// ── Parsers (validated, exported) ────────────────────────────────────────

const GRAINS: readonly TimeGrain[] = [
  "day",
  "week",
  "month",
  "quarter",
  "year",
  "fiscal_quarter",
  "fiscal_year",
] as const;

/**
 * Turn a plan's governed block into a SemanticQuery, or return null.
 *
 * EVERY NAME IS CHECKED against the catalog the analyst actually loaded. A
 * metric the model invented does not become a governed metric by being
 * named in a JSON field called "metrics" — and the failure mode of letting
 * it through is the worst kind: the step would carry a "Governed" badge over
 * SQL that compiles from something nobody signed off, or fail on the server
 * with an error the reader cannot connect to the claim.
 *
 * Returning null is not a refusal to answer. The caller falls back to
 * model-written SQL and the step is shown as ungoverned, which is the honest
 * description of what happened.
 */
export function parseSemanticStep(
  raw: unknown,
  catalog: GovernedModelFields[],
): SemanticQuery | null {
  const o = (raw ?? {}) as Record<string, unknown>;
  const modelName = typeof o.model === "string" ? o.model.trim() : "";
  if (!modelName) return null;
  const model = catalog.find((m) => m.name.toLowerCase() === modelName.toLowerCase());
  if (!model) return null;

  const pick = (v: unknown, allowed: string[]): string[] => {
    const want = Array.isArray(v) ? v : typeof v === "string" ? [v] : [];
    const out: string[] = [];
    for (const item of want) {
      if (typeof item !== "string") continue;
      const hit = allowed.find((a) => a.toLowerCase() === item.trim().toLowerCase());
      if (hit && !out.includes(hit)) out.push(hit);
    }
    return out;
  };

  const metrics = pick(o.metrics, model.metrics);
  const dimensions = pick(o.dimensions, model.dimensions);
  // A governed query with no metric is not a governed query — it is a column
  // listing that would be better served by ordinary SQL.
  if (metrics.length === 0) return null;
  // Any name the plan asked for that the model does not have means the plan
  // was reasoning about a schema that does not exist. Compiling the subset
  // that happened to match would answer a DIFFERENT question, silently.
  const askedMetrics = Array.isArray(o.metrics) ? o.metrics.length : o.metrics ? 1 : 0;
  const askedDims = Array.isArray(o.dimensions) ? o.dimensions.length : o.dimensions ? 1 : 0;
  if (metrics.length !== askedMetrics || dimensions.length !== askedDims) return null;

  const q: SemanticQuery = { model: model.name, metrics };
  if (dimensions.length) q.dimensions = dimensions;

  // Grains: only on dimensions this query actually selected, and only the
  // grains the compiler knows.
  if (o.grains && typeof o.grains === "object") {
    const grains: Record<string, TimeGrain> = {};
    for (const [k, v] of Object.entries(o.grains as Record<string, unknown>)) {
      const dim = dimensions.find((d) => d.toLowerCase() === k.trim().toLowerCase());
      const grain = GRAINS.find((g) => g === String(v).trim().toLowerCase());
      if (dim && grain) grains[dim] = grain;
    }
    if (Object.keys(grains).length) q.grains = grains;
  }

  // Filters reference fields by name too, so they get the same treatment:
  // a filter on a field the model does not have is dropped along with the
  // whole block rather than quietly widening the result.
  if (Array.isArray(o.filters) && o.filters.length) {
    const fields = [...model.metrics, ...model.dimensions];
    const filters: SemanticFilter[] = [];
    for (const f of o.filters as unknown[]) {
      const fo = (f ?? {}) as Record<string, unknown>;
      const field = fields.find(
        (a) =>
          a.toLowerCase() ===
          String(fo.field ?? "")
            .trim()
            .toLowerCase(),
      );
      const op = typeof fo.op === "string" ? fo.op.trim() : "";
      if (!field || !op) return null;
      filters.push({ field, op, value: fo.value } as SemanticFilter);
    }
    if (filters.length) q.filters = filters;
  }

  // ORDER BY, because "top 5" without it is five arbitrary rows.
  //
  // Measured live: a governed "the 5 orders with the largest discount"
  // compiled to a LIMIT with no ordering and returned discounts of 0, 0.65,
  // 0.2… The self-check spotted it and rewrote the SQL by hand, which
  // rescued the answer at the cost of the step's compiled status. Supporting
  // it here keeps the query governed AND correct.
  if (Array.isArray(o.orderBy) && o.orderBy.length) {
    const selectable = [...metrics, ...dimensions];
    const orderBy: NonNullable<SemanticQuery["orderBy"]> = [];
    for (const raw of o.orderBy as unknown[]) {
      const ob = (raw ?? {}) as Record<string, unknown>;
      const name = typeof ob === "string" ? ob : String(ob.field ?? "");
      const field = selectable.find((f) => f.toLowerCase() === name.trim().toLowerCase());
      // Ordering by something the query does not select is not a tidier
      // result, it is a different one — refuse the block as with filters.
      if (!field) return null;
      orderBy.push({
        field,
        dir: String(ob.dir ?? "desc").toLowerCase() === "asc" ? "asc" : "desc",
      });
    }
    if (orderBy.length) q.orderBy = orderBy;
  }

  if (typeof o.limit === "number" && Number.isFinite(o.limit) && o.limit > 0) {
    q.limit = Math.min(Math.trunc(o.limit), ANALYST_ROW_CAP * 20);
  }
  return q;
}

/** A plan's rank block, validated: a column name, a direction (default descending), an optional limit within the scoring cap. */
export function parseScoreRank(raw: unknown): ScoreRank | undefined {
  if (!raw || typeof raw !== "object") return undefined;
  const o = raw as Record<string, unknown>;
  const by =
    typeof o.by === "string" ? o.by.trim() : typeof o.column === "string" ? o.column.trim() : "";
  if (!by) return undefined;
  const desc =
    typeof o.desc === "boolean"
      ? o.desc
      : typeof o.dir === "string"
        ? o.dir.toLowerCase() !== "asc"
        : true;
  const limit =
    typeof o.limit === "number" && o.limit >= 1
      ? Math.min(ANALYST_SCORE_CAP, Math.floor(o.limit))
      : undefined;
  return { by, desc, ...(limit ? { limit } : {}) };
}

export function parseAnalysisPlan(
  raw: unknown,
  /** Governed models in scope. Omitted → no step can claim to be governed. */
  catalog: GovernedModelFields[] = [],
  /** Trained models in scope. Omitted → no step can ask to be scored. */
  models: ScorableModel[] = [],
  /** The question, as the goal of a plan the model collapsed into one bare step. */
  question = "",
): {
  approach: string;
  steps: {
    goal: string;
    semantic?: SemanticQuery;
    score?: { model: string; rank?: ScoreRank };
    forecast?: { model: string; horizon?: number };
  }[];
  /** Set INSTEAD of steps when the analyst needs an answer before it can plan. */
  clarify?: string;
  /** What it would assume if told to proceed anyway. */
  assumption?: string;
} {
  // Tolerant by measurement, like parseSynthesis: models in JSON mode wrap
  // the plan, name the goal key differently, or return plain strings.
  const root = (raw ?? {}) as Record<string, unknown>;
  const o = (root.plan && typeof root.plan === "object" ? root.plan : root) as Record<
    string,
    unknown
  >;
  const approach = typeof o.approach === "string" ? o.approach.trim() : "";
  const isStepLike = (v: unknown): v is Record<string, unknown> =>
    !!v &&
    typeof v === "object" &&
    !Array.isArray(v) &&
    (typeof (v as Record<string, unknown>).goal === "string" ||
      ["score", "scored", "forecast", "semantic"].some(
        (k) =>
          !!(v as Record<string, unknown>)[k] &&
          typeof (v as Record<string, unknown>)[k] === "object",
      ));
  const found = Array.isArray(o.steps)
    ? o.steps
    : Array.isArray(o.analysis_steps)
      ? o.analysis_steps
      : isStepLike(o.steps)
        ? [o.steps]
        : ((Object.values(o).find(Array.isArray) as unknown[] | undefined) ?? []);
  // Measured live, twice in one session: asked for the ten most anomalous
  // orders, the model returned `{ "score": { "model": …, "rank": … } }`
  // and nothing else — the plan collapsed into its one interesting block —
  // and the analyst said "no analysis steps". A bare step-shaped root IS a
  // one-step plan; its goal is the question.
  const list: unknown[] =
    found.length === 0 && isStepLike(o)
      ? [{ ...o, goal: typeof o.goal === "string" && o.goal.trim() ? o.goal : question }]
      : found;
  const goalOf = (s: unknown): string => {
    if (typeof s === "string") return s.trim();
    const obj = (s ?? {}) as Record<string, unknown>;
    for (const k of ["goal", "step", "description", "title", "objective", "name"]) {
      if (typeof obj[k] === "string" && (obj[k] as string).trim()) return (obj[k] as string).trim();
    }
    return "";
  };
  const steps = list
    .map((s) => {
      const goal = goalOf(s);
      const obj = (s ?? {}) as Record<string, unknown>;
      const semantic = parseSemanticStep(obj.semantic ?? obj.governed, catalog);
      // A scored step names a model that is actually in scope, or it is not
      // a scored step — the same rule as a governed block. A name the model
      // invented does not become a prediction by being asked for.
      const scoreRaw = obj.score ?? obj.scored ?? obj.model_score;
      const scoreName =
        scoreRaw && typeof scoreRaw === "object"
          ? (scoreRaw as Record<string, unknown>).model
          : scoreRaw;
      const rankRaw =
        scoreRaw && typeof scoreRaw === "object"
          ? (scoreRaw as Record<string, unknown>).rank
          : undefined;
      const rank = parseScoreRank(rankRaw);
      let score =
        typeof scoreName === "string" &&
        models.some((m) => m.name === scoreName.trim() && m.task !== "forecast")
          ? { model: scoreName.trim(), ...(rank ? { rank } : {}) }
          : undefined;
      // A forecast step names a FORECAST model — no SQL, the model's own periods.
      const fRaw = obj.forecast;
      const fName =
        fRaw && typeof fRaw === "object" ? (fRaw as Record<string, unknown>).model : fRaw;
      const fHorizon =
        fRaw && typeof fRaw === "object" ? (fRaw as Record<string, unknown>).horizon : undefined;
      let forecast =
        typeof fName === "string" &&
        models.some((m) => m.name === fName.trim() && m.task === "forecast")
          ? {
              model: fName.trim(),
              ...(typeof fHorizon === "number" && fHorizon >= 1
                ? { horizon: Math.min(120, Math.floor(fHorizon)) }
                : {}),
            }
          : undefined;
      // A goal that NAMES a model in scope is scored by it even when the
      // planner forgot the block. Measured live: "estimate their net_usd
      // with the revenue_facts model" came back with no score, was written
      // as SQL over the actual values, and the write-up called those the
      // model's estimates. Naming the model is the request.
      if (!score && !forecast) {
        const named = models.find((m) => namesModel(goal, m.name));
        if (named && named.task === "forecast") forecast = { model: named.name };
        else if (named) score = { model: named.name, ...(rank ? { rank } : {}) };
      }
      return {
        goal,
        ...(semantic ? { semantic } : {}),
        ...(score ? { score } : {}),
        ...(forecast ? { forecast } : {}),
      };
    })
    .filter((s) => s.goal.length > 0)
    .slice(0, MAX_ANALYSIS_STEPS);
  // A clarification is only honoured when the model ALSO produced no plan.
  // Both together means it hedged: it knew how to proceed and asked anyway,
  // and stopping there would make the feature a nag.
  const clarify = typeof o.clarify === "string" ? o.clarify.trim() : "";
  if (steps.length === 0 && clarify) {
    return {
      approach: "",
      steps: [],
      clarify,
      assumption: typeof o.assumption === "string" ? o.assumption.trim() : "",
    };
  }
  if (steps.length === 0) {
    // An EMPTY reply and a badly-shaped one are different failures, and the
    // empty one has a specific cause worth naming: a reasoning model that
    // spent its whole completion budget thinking. Saying "try rephrasing"
    // for that sends the user to fix the one thing that was fine.
    if (Object.keys(root).length === 0) {
      throw new Error(
        "The model returned an empty plan — it likely spent its completion budget on reasoning. " +
          "Try a question with fewer parts, or an analyst on a model with more headroom.",
      );
    }
    throw new Error("The analyst returned no analysis steps — try rephrasing the question.");
  }
  return { approach, steps };
}

/**
 * The synthesis reply, tolerantly. Models in JSON mode legitimately return a
 * bare JSON string (JSON.parse('"text"') succeeds), or wrap the markdown
 * under a key other than "answer" — measured live with gpt-5-mini, whose
 * write-up came back shaped so the strict `.answer` read produced the
 * "no write-up" fallback on a perfectly good analysis.
 */
/**
 * A structured answer, as prose a person can read.
 *
 * Measured live with gpt-4o-mini on a scored step: asked for `{ "answer":
 * "markdown" }`, it returned `{ "answer": { "orders": [ { "order_id": 1000,
 * "predicted_plan": "pro", "probability": 0.9479 }, … ] }, "caveats": [...] }`
 * — a perfectly good answer as data — and the strict string read produced
 * "produced no write-up" over a finished analysis, twice. An array of flat
 * objects becomes a table, an object becomes a list, and anything stranger
 * is shown as JSON rather than as nothing.
 */
export function structuredToMarkdown(value: unknown, depth = 0): string {
  const isFlat = (v: unknown): v is Record<string, unknown> =>
    !!v &&
    typeof v === "object" &&
    !Array.isArray(v) &&
    Object.values(v).every((x) => x === null || typeof x !== "object");
  const cell = (v: unknown): string =>
    v === null || v === undefined
      ? "—"
      : typeof v === "number"
        ? String(Number(v.toFixed(4)))
        : typeof v === "object"
          ? JSON.stringify(v)
          : String(v).replace(/\|/g, "\\|");
  if (value === null || value === undefined) return "";
  if (typeof value !== "object") return String(value);
  if (Array.isArray(value)) {
    if (value.length === 0) return "";
    if (value.every(isFlat)) {
      const cols: string[] = [];
      for (const row of value)
        for (const k of Object.keys(row)) if (!cols.includes(k)) cols.push(k);
      return (
        `| ${cols.join(" | ")} |\n| ${cols.map(() => "---").join(" | ")} |\n` +
        value.map((row) => `| ${cols.map((c) => cell(row[c])).join(" | ")} |`).join("\n")
      );
    }
    return value
      .map((v) => `- ${structuredToMarkdown(v, depth + 1).replace(/\n/g, "\n  ")}`)
      .join("\n");
  }
  const o = value as Record<string, unknown>;
  const label = (k: string) => k.replace(/_/g, " ");
  return Object.entries(o)
    .map(([k, v]) => {
      if (v !== null && typeof v === "object") {
        const body = structuredToMarkdown(v, depth + 1);
        return depth === 0
          ? `**${label(k)}**\n\n${body}`
          : `- ${label(k)}:\n  ${body.replace(/\n/g, "\n  ")}`;
      }
      return `- ${label(k)}: ${cell(v)}`;
    })
    .join("\n\n");
}

export function parseSynthesis(raw: unknown): string {
  if (typeof raw === "string") return raw.trim();
  const o = (raw ?? {}) as Record<string, unknown>;
  const caveats = ["caveats", "caveat", "notes"]
    .map((k) => o[k])
    .find((v) => Array.isArray(v) || typeof v === "string");
  const withCaveats = (answer: string): string => {
    if (!answer) return answer;
    const list = Array.isArray(caveats)
      ? caveats.filter((c): c is string => typeof c === "string" && c.trim().length > 0)
      : typeof caveats === "string" && caveats.trim()
        ? [caveats.trim()]
        : [];
    return list.length
      ? `${answer}\n\n**Caveats**\n\n${list.map((c) => `- ${c}`).join("\n")}`
      : answer;
  };
  for (const k of ["answer", "markdown", "text", "findings", "summary"]) {
    const v = o[k];
    if (typeof v === "string" && v.trim()) return withCaveats(v.trim());
    // The answer as DATA rather than prose — rendered, not discarded.
    if (v !== null && typeof v === "object") {
      const rendered = structuredToMarkdown(v).trim();
      if (rendered) return withCaveats(rendered);
    }
  }
  // A single string value under an unexpected key is still the answer.
  const strings = Object.values(o).filter(
    (v): v is string => typeof v === "string" && v.trim().length > 0,
  );
  return strings.length === 1 ? withCaveats(strings[0].trim()) : "";
}

/**
 * The synthesis reply: the write-up AND the questions it makes worth asking
 * next. Follow-ups are optional — an analysis with none is still complete,
 * so a missing or malformed list never costs the user their answer.
 */
export function parseSynthesisReply(raw: unknown): { answer: string; followUps: string[] } {
  const answer = parseSynthesis(raw);
  const o = (raw ?? {}) as Record<string, unknown>;
  const list = ["follow_ups", "followUps", "next_questions", "suggestions"]
    .map((k) => o[k])
    .find(Array.isArray) as unknown[] | undefined;
  const followUps = (list ?? [])
    .map((q) => (typeof q === "string" ? q.trim() : ""))
    .filter((q) => q.length > 0 && q.length <= 160)
    .slice(0, MAX_FOLLOW_UPS);
  return { answer, followUps };
}

export function parseCheckResponse(
  raw: unknown,
  stepCount: number,
): {
  checks: Array<{ verdict: "pass" | "suspect"; note: string; refined_sql?: string }>;
  headline: number;
} {
  const o = (raw ?? {}) as { checks?: unknown; headline?: unknown };
  const list = Array.isArray(o.checks) ? o.checks : [];
  const checks = Array.from({ length: stepCount }, (_, i) => {
    const c = (list[i] ?? {}) as { verdict?: unknown; note?: unknown; refined_sql?: unknown };
    const verdict = c.verdict === "suspect" ? ("suspect" as const) : ("pass" as const);
    const note = typeof c.note === "string" ? c.note.trim() : "";
    const refined =
      typeof c.refined_sql === "string" && c.refined_sql.trim().length > 0
        ? c.refined_sql.trim()
        : undefined;
    return { verdict, note, ...(refined ? { refined_sql: refined } : {}) };
  });
  const h = typeof o.headline === "number" ? Math.trunc(o.headline) : 0;
  const headline = h >= 0 && h < stepCount ? h : 0;
  return { checks, headline };
}

/** Rows small enough to hand the model verbatim rather than summarised. */
export const QUOTE_ROWS_UP_TO = 12;

/**
 * When a step's result compares two periods by dimension, decompose it.
 *
 * "Why did it move" is the question every BI tool gets asked and few
 * answer. The model already writes SQL that fetches both periods side by
 * side; recognising that shape and doing the CONTRIBUTION ARITHMETIC here
 * turns it into an answer — computed, ranked and reproducible, rather than
 * a paragraph of plausible attributions. Returns null whenever the shape is
 * anything else, and the ordinary path continues untouched.
 */
export function driversForStep(step: {
  columns?: string[];
  rows?: Record<string, unknown>[];
}): DriverAnalysis | null {
  if (!step.columns || !step.rows) return null;
  const inputs = driverInputsFrom(step.columns, step.rows);
  if (!inputs || inputs.length === 0) return null;
  const analysis = analyseDrivers(inputs);
  // Two periods that are identical everywhere are not a change story, and
  // labelling them one would invent significance the data does not have.
  if (analysis.contributions.every((c) => c.change === 0)) return null;
  return analysis;
}

/**
 * What the check and the write-up are TOLD a step returned.
 *
 * describeResultFacts summarises — total, max, min, row count — which is
 * right for a thousand rows and actively harmful for three. Fed only
 * summaries, the model wrote "the per-segment totals are missing" while the
 * three per-segment totals sat in the table directly above it, and hedged
 * the same way on every small result. Measured on two live runs before
 * anyone noticed the write-up was under-reporting its own evidence.
 *
 * So: quote small results in full, summarise big ones, and say which.
 */
export function describeStepResult(
  result: QueryResult,
  maxRows = QUOTE_ROWS_UP_TO,
  /** Columns a trained model added to the rows — listed as estimates, never fed to the arithmetic. */
  estimates: string[] = [],
): string {
  // Two shapes get arithmetic attached before the model ever sees them, so
  // the write-up cites computed values instead of eyeballing columns: a
  // two-period breakdown gets contribution analysis, and a time series gets
  // its trend, outliers and (only when the history supports one) a labelled
  // projection.
  //
  // The arithmetic reads OBSERVED columns only. A scored step's rows carry
  // the model's columns too, and measured live the driver detector read
  // `order_id | prediction | probability` as a two-period breakdown by
  // prediction, computed the "contribution" of order_id -> probability, and
  // the reviewer repeated its "-11,054.852 total change" as a concern that
  // the write-up then listed as a caveat. An estimate is quoted in the rows,
  // marked as one; it is never a period, a series or a driver.
  const estimated = estimates.filter((c) => result.columns.includes(c));
  const observed = {
    columns: result.columns.filter((c) => !estimated.includes(c)),
    rows: result.rows,
  };
  const drivers = driversForStep(observed);
  const driverBlock = drivers ? `\n\nCONTRIBUTION ANALYSIS:\n${describeDrivers(drivers)}` : "";
  const series = seriesFrom(observed.columns, result.rows);
  const reading = series ? readSeries(series) : null;
  const seriesBlock = reading ? `\n\n${describeSeries(reading, forecastSeries(series!))}` : "";
  const extra = driverBlock + seriesBlock;
  const estimateNote = estimated.length
    ? `\nMODEL ESTIMATES (added to the rows after the query; in no table): ${estimated.join(", ")}`
    : "";
  if (result.rows.length === 0 || result.rows.length > maxRows) {
    return describeResultFacts(result) + estimateNote + extra;
  }
  const cell = (v: unknown) => {
    if (v === null || v === undefined) return "null";
    const s = typeof v === "number" ? String(Number(v.toFixed(4))) : String(v);
    return s.length > 60 ? `${s.slice(0, 57)}…` : s;
  };
  const rows = result.rows
    .map((r) => result.columns.map((c) => `${c}=${cell(r[c])}`).join(" | "))
    .join("\n");
  const name = (c: string) => (estimated.includes(c) ? `${c} (model estimate)` : c);
  return (
    `${result.rows.length} row${result.rows.length === 1 ? "" : "s"}, ` +
    `columns: ${result.columns.map(name).join(", ")}\n${rows}${extra}`
  );
}

/**
 * The one line the write-up is told about a scored step: the model, its
 * version and metric, its health, and any ranking the platform applied.
 */
export function scoredLabel(s: ScoredDisclosure): string {
  const ranked = s.ranked
    ? `; ranked by ${s.ranked.by} ${s.ranked.desc ? "desc" : "asc"}${s.ranked.limit ? `, top ${s.ranked.limit} of ${s.ranked.of} scored` : ""}`
    : "";
  const periods = s.forecast
    ? ` (${s.rowsScored} ${s.forecast.period ?? "period"}s${s.forecast.lastObserved ? ` after ${s.forecast.lastObserved}` : ""})`
    : "";
  return `${s.model} v${s.version ?? "?"}${s.metric ? ` (${s.metric})` : ""}${periods}${s.health ? `; ${s.health}` : ""}${ranked}`;
}

/**
 * What the check and the write-up are told a step returned: the result,
 * with the columns a model added marked as estimates and kept out of the
 * arithmetic. One helper so the three prompts that read a result cannot
 * disagree about which columns the SQL produced.
 */
export function stepFacts(result: QueryResult | null, step: Pick<AnalystStep, "scored">): string {
  // A scored step's rows ARE the answer — up to the scoring cap, they are
  // quoted in full. Measured live: fifteen scored orders were summarised
  // (rows > QUOTE_ROWS_UP_TO), so the write-up saw "order_id total=22104"
  // and three per-class maxima, and built its findings table out of those.
  return result
    ? describeStepResult(
        result,
        step.scored ? Math.max(QUOTE_ROWS_UP_TO, ANALYST_SCORE_CAP) : QUOTE_ROWS_UP_TO,
        step.scored?.columns ?? [],
      )
    : "(no result)";
}

/**
 * Does this result have a shape worth drawing?
 *
 * Cheap and honest, and it runs BEFORE any LLM call: a step with no rows,
 * or with nothing but labels, has nothing to plot, and asking a model to
 * chart it wastes a call to be told "table". Everything else is offered to
 * suggestChart, which makes the actual choice.
 */
export function isChartableShape(result: {
  columns: string[];
  rows: Record<string, unknown>[];
}): boolean {
  if (result.rows.length === 0) return false;
  const numeric = result.columns.filter((c) =>
    result.rows.some((r) => typeof r[c] === "number" && Number.isFinite(r[c] as number)),
  );
  if (numeric.length === 0) return false;
  // One row and one number is a KPI; anything more needs a category to plot
  // against, which is any non-numeric column.
  if (result.rows.length === 1) return result.columns.length <= 3;
  return numeric.length > 0 && result.columns.length >= 2;
}

/**
 * Which step's visual leads the answer.
 *
 * The self-check nominates a headline; it only counts if that step actually
 * produced a chart. Otherwise the first step that did leads, and if none
 * did the turn simply has no lead visual.
 */
export function leadChartStep(steps: AnalystStep[], headline: number): number | undefined {
  const drawable = (i: number) => steps[i]?.chart && steps[i].chart.type !== "table";
  if (drawable(headline)) return headline;
  const first = steps.findIndex((_, i) => drawable(i));
  return first >= 0 ? first : undefined;
}

/**
 * Suggest a chart for EVERY chartable step, concurrently.
 *
 * Exported with an injectable suggester so a test can prove that all of
 * them get one — the version that charted only the headline is exactly the
 * regression this guards, and it is invisible to a test of the pure
 * helpers alone.
 */
export async function chartEveryStep(args: {
  turn: AnalystTurn;
  results: (QueryResult | null)[];
  question: string;
  model?: string;
  /** Model transport for the default suggester; see LlmJsonFn. */
  llm?: LlmJsonFn;
  suggest?: (a: {
    question: string;
    result: QueryResult;
    plan: BiPlan;
    model?: string;
    llm?: LlmJsonFn;
  }) => Promise<ChartSpec>;
}): Promise<void> {
  const suggest = args.suggest ?? suggestChart;
  await Promise.all(
    args.turn.steps.map(async (step, i) => {
      const res = args.results[i];
      if (!res || !isChartableShape(res)) return;
      try {
        step.chart = await suggest({
          // The STEP's goal, not the whole question: the chart has to fit
          // what this query returned, and the overall question describes
          // something wider than any single step.
          question: step.goal,
          result: res,
          plan: { intent: step.goal, tables: [], metrics: [], breakdowns: [] },
          model: args.model,
          llm: args.llm,
        });
      } catch {
        /* a chart is a nice-to-have; the result table still stands */
      }
    }),
  );
}

// ── The loop ─────────────────────────────────────────────────────────────

export async function runAnalystTurn(args: {
  question: string;
  datasets: DatasetMeta[];
  semantics: Map<string, SemanticEntry>;
  metrics: SavedMetric[];
  /** Prior turns of THIS thread, for conversational continuity. */
  priorTurns: AnalystTurn[];
  /** Encoded "provider::model" choice — the analyst's pinned model. */
  model?: string;
  /** Override SQL execution (warehouse scope); omitted = local DuckDB. */
  execute?: (sql: string) => Promise<QueryResult>;
  /** Human name of the engine when `execute` is provided. */
  dialect?: string;
  /** Governed models the plan may compile against. Empty = none, and no
   *  step can be marked governed. */
  catalog?: GovernedModelFields[];
  /**
   * Run a compiled semantic query. Injected rather than imported so the loop
   * stays testable and so compilation keeps happening SERVER-side, where the
   * full model, its row filters and its column masks live — the browser only
   * ever holds field names.
   */
  runSemantic?: (q: SemanticQuery) => Promise<{
    sql: string;
    columns: string[];
    rows: Record<string, unknown>[];
    rollup?: string;
    access_note?: string;
    /** The rows are a prefix: the governed query has more than were returned. */
    truncated?: boolean;
  }>;
  /**
   * How to reach the model. Defaults to the browser session, which is the
   * only thing an EMBED does not have — a public embed runs this same loop
   * with a server-side transport authenticating as the analyst's owner, so
   * the reasoning an anonymous visitor gets is the reasoning the owner gets.
   */
  llm?: LlmJsonFn;
  /** Trained models the plan may score rows with. Empty = no scored steps. */
  models?: ScorableModel[];
  /**
   * Score a step's rows with a registry model. Injected like runSemantic and
   * for the same reason: scoring happens SERVER-side, where the model, its
   * feature view and the owner's grants live — the browser only ever holds
   * model names. Absent means a scored step is planned but cannot run, and
   * says so.
   */
  scoreRows?: (req: { model: string; rows: Record<string, unknown>[] }) => Promise<ScoreRowsResult>;
  /** A forecast model's projection, server-side like scoreRows. Absent means a forecast step cannot run, and says so. */
  forecast?: (req: { model: string }) => Promise<ForecastResult>;
  /**
   * Names of trained models the user could enable for this analyst but has
   * not — so a question naming one gets "not enabled for this analyst"
   * rather than "no such model", and points at the setting.
   */
  modelsOutsideScope?: string[];
  onUpdate: (turn: AnalystTurn) => void;
}): Promise<AnalystTurn> {
  const ask: LlmJsonFn = args.llm ?? llmJson;
  const turn: AnalystTurn = {
    question: args.question,
    steps: [],
    status: "planning",
    at: new Date().toISOString(),
    // Stamped HERE, not read from the analyst at render time: the analyst's
    // model is editable, and a turn must keep saying which model actually
    // answered it.
    model: args.model,
  };
  const emit = () => args.onUpdate({ ...turn, steps: turn.steps.map((s) => ({ ...s })) });
  emit();

  // De-duplicates identical SQL WITHIN this turn only. Same query, same
  // instant, so the shared result needs no disclosure — and it is discarded
  // when the turn ends, because between two questions the data can move.
  const queryCache = createTurnCache<QueryResult>();
  const sourceKey = args.execute ? `wh:${args.dialect ?? "warehouse"}` : "local";
  const runSql = async (sql: string): Promise<QueryResult> => {
    const clean = assertSelectOnly(sql);
    return queryCache.run(resultCacheKey(sourceKey, clean), async () =>
      args.execute
        ? await args.execute(clean)
        : await (await import("@/lib/sqlEngine")).runQuery(clean),
    );
  };
  const captureResult = (step: AnalystStep, res: QueryResult) => {
    step.columns = res.columns;
    // total_matched is the engine's pre-cap count; rows.length is only the
    // truth when nothing upstream capped. Preferring it is what lets the
    // "(showing 50 of 108)" disclosure and the reshape pass see engine-level
    // truncation, not just trace-level trimming.
    step.rowCount = res.total_matched ?? res.rows.length;
    step.rows = res.rows.slice(0, ANALYST_ROW_CAP);
  };
  // Facts are described from the FULL result, then the step keeps a capped
  // sample — the check must see true magnitudes, the store must stay small.
  const results: (QueryResult | null)[] = [];

  // Score a step's rows with the model its plan named. The step's own sample
  // (≤ ANALYST_SCORE_CAP, the tool's cap too) is what gets scored, and the
  // prediction columns join BOTH the step and the result the check and the
  // write-up read — a predicted column is never one the findings could not
  // have seen. A scoring that fails leaves the rows unscored and SAYS so;
  // the analyst never fills a prediction in itself.
  const scoreStep = async (step: AnalystStep, res: QueryResult, i: number) => {
    if (!step.score) return;
    if (!args.scoreRows) {
      step.check = {
        verdict: "suspect",
        note: `The plan asked to score these rows with ${step.score.model}, but scoring is not available here — the rows below are unscored.`,
      };
      delete step.score;
      return;
    }
    step.status = "scoring";
    emit();
    try {
      const out = await args.scoreRows({
        model: step.score.model,
        rows: res.rows.slice(0, ANALYST_SCORE_CAP),
      });
      if (!out.ok) throw new Error(out.error);
      // total_matched carries the true pre-cap count through, so
      // "(showing 50 of 108)" and "scored 50 of 108" can both be said.
      // The MOST / LEAST / TOP-N by the model's output is decided HERE, on
      // the scored rows — the one place the output exists.
      const ranked = step.score.rank
        ? rankScoredRows(out.rows, step.score.rank, out.columns)
        : null;
      const rows = ranked ? ranked.rows : out.rows;
      const scoredResult: QueryResult = {
        ...res,
        columns: out.columns,
        rows,
        row_count: rows.length,
        total_matched: res.total_matched ?? res.rows.length,
      };
      captureResult(step, scoredResult);
      results[i] = scoredResult;
      step.scored = { ...out.scored, ranked: ranked?.applied ?? null };
      if (ranked?.note) step.check = { verdict: "suspect", note: ranked.note };
    } catch (e) {
      step.check = {
        verdict: "suspect",
        note: `Could not score with ${step.score.model}: ${(e as Error).message}. The rows below are unscored.`,
      };
      delete step.score;
    }
  };

  // A forecast step asks a FORECAST model for its projection: no SQL, the
  // rows are the model's periods. A projection that cannot be produced is
  // a failed step, not a quiet table of nothing.
  const forecastStep = async (step: AnalystStep, i: number) => {
    if (!step.forecast) return;
    if (!args.forecast) {
      step.error = `The plan asked ${step.forecast.model} for a forecast, but forecasting is not available here.`;
      step.status = "error";
      results[i] = null;
      return;
    }
    step.status = "scoring";
    emit();
    const out = await args.forecast({ model: step.forecast.model });
    if (!out.ok) {
      step.error = `Could not forecast with ${step.forecast.model}: ${out.error}`;
      step.status = "error";
      results[i] = null;
      return;
    }
    const horizon = step.forecast.horizon;
    const rows = horizon && horizon > 0 ? out.rows.slice(0, horizon) : out.rows;
    const res: QueryResult = {
      columns: out.columns,
      rows,
      row_count: rows.length,
      total_matched: rows.length,
      capped: false,
      duration_ms: 0,
    };
    captureResult(step, res);
    results[i] = res;
    step.scored = { ...out.scored, rowsScored: rows.length };
    step.status = "done";
  };

  try {
    // 1. PLAN
    await ensureGovernedCatalog();
    const schema = describeSchema(args.datasets, args.semantics, args.metrics);
    const prior = priorContext(args.priorTurns);
    const catalog = args.catalog ?? [];
    const planPrompt = buildAnalysisPlanPrompt({
      schema,
      question: args.question,
      prior,
      catalog,
      models: args.models,
    });
    let plan = parseAnalysisPlan(
      await ask<unknown>({ ...planPrompt, model: args.model, maxTokens: ANALYST_TOKENS.plan }),
      catalog,
      args.models ?? [],
      args.question,
    );
    // Asked again after the user accepted the assumption: one more try,
    // told so in plain words, before honouring a question it still insists on.
    if (plan.clarify && /Proceed with this assumption:/.test(args.question)) {
      plan = parseAnalysisPlan(
        await ask<unknown>({
          ...planPrompt,
          systemPrompt:
            planPrompt.systemPrompt +
            "\n\nYou asked once and the user answered with the assumption above. Return steps now; " +
            "a second clarify is a refusal to work.",
          model: args.model,
          maxTokens: ANALYST_TOKENS.plan,
        }),
        catalog,
        args.models ?? [],
        args.question,
      );
    }
    // The question named a model that does not exist and the plan reached
    // for another one: ask, rather than answer "which five are most at risk"
    // with a clustering model standing in for a churn model nobody has.
    // A model the user HAS but did not enable for this analyst is named as
    // exactly that, whether the plan substituted or asked on its own.
    const missing =
      plan.steps.some((s) => s.score || s.forecast) || plan.clarify
        ? namedModelMissing(args.question, [
            ...(args.models ?? []).map((m) => m.name),
            ...catalog.map((c) => c.name),
          ])
        : null;
    const outside =
      missing && !/Proceed with this assumption:/.test(args.question)
        ? (args.modelsOutsideScope ?? []).find((n) => {
            const words = missing
              .toLowerCase()
              .split(/[\s\u00b7-]+/)
              .filter(Boolean);
            return words.every((w) => n.toLowerCase().includes(w));
          })
        : undefined;
    if (outside) {
      const names = (args.models ?? []).map((m) => `"${m.name}"`).join(", ");
      plan = {
        approach: "",
        steps: [],
        clarify:
          `"${outside}" exists but is not enabled for this analyst` +
          (names
            ? ` — its predictive models are ${names}.`
            : " — it has no predictive models enabled.") +
          " Enable it under the analyst's settings (the pencil on its card), or ask with one it may use.",
        assumption: "Answer from the data alone, without a trained model",
      };
    }
    if (outside) {
      // Said above; nothing to strip and nothing more to ask.
    } else if (missing && /Proceed with this assumption:/.test(args.question)) {
      // The user already chose to go on; a plan that still reaches for
      // another model is stripped of its scoring, never trusted. Measured
      // live: the planner's own second assumption was "the churn model is
      // the one defined in the schema" — there is none — and accepting it
      // would have scored the rows with the clustering model again.
      plan = {
        ...plan,
        approach:
          `No trained model named "${missing}" exists; answered from the data alone. ` +
          plan.approach,
        steps: plan.steps.map(({ score: _score, forecast: _forecast, ...rest }) => rest),
      };
    } else if (missing) {
      const names = (args.models ?? []).map((m) => `"${m.name}"`).join(", ");
      plan = {
        approach: "",
        steps: [],
        clarify:
          `No trained model named "${missing}" is available to this analyst` +
          (names ? `; it can use ${names}.` : ".") +
          " Which should it use, or should it answer without a model?",
        assumption: "Answer from the data alone, without a trained model",
      };
    }
    // 1b. STOP AND ASK, when proceeding would mean inventing the question.
    // A guess that runs produces confident numbers with the assumption
    // buried in SQL nobody reads; a question costs one exchange and leaves
    // the analysis defensible. The assumption is offered alongside so the
    // usual answer is one click, not a retyped question.
    if (plan.clarify) {
      turn.clarify = plan.clarify;
      turn.assumption = plan.assumption;
      turn.status = "clarifying";
      emit();
      return turn;
    }
    turn.approach = plan.approach;
    turn.steps = plan.steps.map((s) => ({
      goal: s.goal,
      ...(s.semantic ? { semantic: s.semantic } : {}),
      ...(s.score ? { score: s.score } : {}),
      ...(s.forecast ? { forecast: s.forecast } : {}),
      status: "pending" as const,
    }));
    turn.status = "working";
    emit();

    // 2. QUERY each step, CONCURRENTLY.
    //
    // Safe because no step consumes another's output: each step's SQL is
    // written from its own goal, and `results` is read only after this block.
    // See lib/analystParallel — if a step ever comes to depend on an earlier
    // step's rows, this has to become sequential again, because parallelism
    // would not fail loudly, it would produce plausible numbers.
    //
    // The trace still reads top to bottom: steps keep their positions and each
    // renders its own status, so the reader sees them finish out of order
    // rather than seeing them reordered.
    await mapWithConcurrency(turn.steps, ANALYST_STEP_CONCURRENCY, async (step, i) => {
      step.status = "writing_sql";
      emit();
      // A scored step's goal carries what the SQL must return for scoring.
      const sqlGoal = scoringSqlGoal(step, args.models);
      const stepPlan: BiPlan = {
        intent: `One step of a larger analysis. Overall question: ${args.question}`,
        tables: [],
        metrics: [],
        breakdowns: [],
      };
      try {
        // A GOVERNED STEP DOES NOT ASK THE MODEL FOR SQL. The compiler turns
        // the model's own metric definitions into the query — including the
        // fan-out refusals, rollup routing and row filters that a hand-written
        // SELECT has no way to honour. If compiling fails, the step falls back
        // to written SQL and LOSES its governed marking rather than keeping a
        // badge it can no longer justify.
        let compiled = false;
        if (step.semantic && args.runSemantic) {
          try {
            const res = await args.runSemantic(step.semantic);
            step.sql = res.sql;
            step.governed = {
              model: step.semantic.model,
              rollup: res.rollup,
              accessNote: res.access_note,
            };
            step.status = "running";
            emit();
            // `capped: false` used to be written here unconditionally — a
            // claim of completeness over a result the runner had cut at its
            // cap. The runner now says; the step says after it, in the note
            // the self-check keeps and the write-up reads.
            const governedResult: QueryResult = {
              columns: res.columns,
              rows: res.rows,
              row_count: res.rows.length,
              total_matched: res.rows.length,
              capped: res.truncated === true,
              duration_ms: 0,
            };
            captureResult(step, governedResult);
            if (res.truncated) {
              step.check = {
                verdict: "suspect",
                note:
                  `Partial: the governed model returned the first ${res.rows.length} groups of a larger ` +
                  `result, so totals and rankings from this step may be incomplete — narrow with a ` +
                  `filter or a coarser grain to see everything.`,
              };
            }
            results[i] = governedResult;
            await scoreStep(step, governedResult, i);
            step.status = "done";
            emit();
            compiled = true;
          } catch (e) {
            // Say what was attempted. A governed step that silently becomes an
            // ungoverned one teaches people the badge means nothing.
            step.governed = undefined;
            delete step.semantic;
            step.check = {
              verdict: "suspect",
              note:
                `The governed model could not answer this step (${(e as Error).message}), ` +
                `so the SQL below was written by the analyst instead of compiled.`,
            };
          }
        }
        // `return` rather than `continue`: this is now a callback per step,
        // and returning ends THIS step, not the whole batch.
        if (compiled) {
          emit();
          return;
        }
        if (step.forecast) {
          await forecastStep(step, i);
          emit();
          return;
        }
        step.sql = await generateSql({
          question: sqlGoal,
          plan: stepPlan,
          datasets: args.datasets,
          semantics: args.semantics,
          metrics: args.metrics,
          dialect: args.dialect,
          localEngine: args.execute ? undefined : "duckdb",
          model: args.model,
          llm: ask,
        });
        step.status = "running";
        emit();
        let res: QueryResult;
        try {
          res = await runSql(step.sql);
        } catch (e) {
          // One repair pass with the engine's own error, like the BI analyst.
          step.sql = await generateSql({
            question: sqlGoal,
            plan: stepPlan,
            datasets: args.datasets,
            semantics: args.semantics,
            metrics: args.metrics,
            dialect: args.dialect,
            localEngine: args.execute ? undefined : "duckdb",
            model: args.model,
            llm: ask,
            repair: { sql: step.sql, error: (e as Error).message },
          });
          emit();
          res = await runSql(step.sql);
        }
        captureResult(step, res);
        results[i] = res;
        // One reshape pass when the complete answer would not fit in the
        // trace: ask for the same analysis in a <= cap shape (aggregate /
        // bucket / pivot) instead of silently analysing a truncated result.
        // Best-effort — if the rewrite fails or is still too tall, the
        // original result stands and the "(showing N of M)" disclosure does
        // the honest work. Never more than one attempt.
        if ((step.rowCount ?? 0) > ANALYST_ROW_CAP) {
          try {
            const reshaped = await generateSql({
              question: sqlGoal,
              plan: stepPlan,
              datasets: args.datasets,
              semantics: args.semantics,
              metrics: args.metrics,
              dialect: args.dialect,
              localEngine: args.execute ? undefined : "duckdb",
              model: args.model,
              llm: ask,
              reshape: { sql: step.sql, rowCount: step.rowCount ?? 0, cap: ANALYST_ROW_CAP },
            });
            const res2 = await runSql(reshaped);
            if (res2.rows.length <= ANALYST_ROW_CAP && res2.rows.length > 0) {
              step.sql = reshaped;
              captureResult(step, res2);
              results[i] = res2;
            }
          } catch {
            /* keep the original result + its truncation disclosure */
          }
        }
        // Scored AFTER the reshape, on the rows the step will actually show.
        await scoreStep(step, results[i] as QueryResult, i);
        step.status = "done";
      } catch (e) {
        step.error = (e as Error).message;
        step.status = "error";
        results[i] = null;
      }
      emit();
    });
    if (turn.steps.every((s) => s.status === "error")) {
      throw new Error(`Every analysis step failed — last error: ${turn.steps.at(-1)?.error}`);
    }

    // 3. SELF-CHECK (one call across all steps; refined SQL re-executes)
    turn.status = "checking";
    turn.steps.forEach((s) => {
      if (s.status === "done") s.status = "checking";
    });
    emit();
    const checkPrompt = buildCheckPrompt({
      question: args.question,
      steps: turn.steps.map((s, i) => ({
        goal: s.goal,
        sql: s.sql,
        facts: stepFacts(results[i], s),
        error: s.error,
        scored:
          s.scored && !s.forecast
            ? {
                model: s.scored.model,
                columns: s.scored.columns ?? [],
                ranked: s.scored.ranked
                  ? `${s.scored.ranked.by} ${s.scored.ranked.desc ? "desc" : "asc"}${s.scored.ranked.limit ? `, top ${s.scored.ranked.limit} of ${s.scored.ranked.of}` : ""}`
                  : null,
              }
            : undefined,
        forecast: s.forecast
          ? {
              model: s.forecast.model,
              period: s.scored?.forecast?.period ?? null,
              periods: s.scored?.rowsScored,
              lastObserved: s.scored?.forecast?.lastObserved ?? null,
            }
          : undefined,
      })),
      catalog,
    });
    let headline = 0;
    try {
      const checked = parseCheckResponse(
        await ask<unknown>({
          ...checkPrompt,
          model: args.model,
          maxTokens: ANALYST_TOKENS.check,
        }),
        turn.steps.length,
      );
      headline = checked.headline;
      for (let i = 0; i < turn.steps.length; i++) {
        const step = turn.steps[i];
        const c = checked.checks[i];
        if (step.status === "error") continue;
        // A note written BEFORE the check — a governed compile that fell back
        // to written SQL, a scoring that failed — is a fact about how this
        // step was produced, and the check's verdict is a fact about the SQL.
        // The verdict used to replace the note, so "the governed model could
        // not answer this step" vanished behind a green "pass". Both are kept.
        const pre = step.check;
        // A correction that reads the model's columns cannot run — they
        // exist in no table — and the prompt rule alone did not hold
        // (measured: `ORDER BY anomaly_score` proposed anyway). Refused HERE,
        // and said, so the original, successful result stands in the open.
        const touches = c.refined_sql
          ? (step.scored?.columns ?? []).filter((col) => namesModel(c.refined_sql!, col))
          : [];
        if (c.refined_sql && step.forecast) {
          step.check = {
            verdict: c.verdict,
            note: `${c.note || "Self-review proposed a correction"} (a forecast step has no SQL to correct; the model's projection stands.)`,
          };
        } else if (c.refined_sql && touches.length > 0) {
          step.check = {
            verdict: "suspect",
            note:
              `${pre ? `${pre.note} ` : ""}${c.note || "Self-review proposed a correction"} — the proposed ` +
              `correction reads the model's column${touches.length === 1 ? "" : "s"} ${touches.join(", ")}, ` +
              `which no query can (a model output exists in no table); the original result above stands. ` +
              `To rank by a model output, the plan asks for "rank" and the platform orders the scored rows.`,
          };
        } else if (c.refined_sql) {
          try {
            const res = await runSql(c.refined_sql);
            step.sql = c.refined_sql;
            // A REFINED STEP IS NO LONGER COMPILED. The correction is SQL the
            // model wrote, replacing what the compiler produced, so the badge
            // would now vouch for a query the semantic layer never saw —
            // the same lie the edit path already refuses to tell. Measured
            // live: a governed "top 5" compiled without ORDER BY, the check
            // rewrote it correctly, and the step kept its governed marking.
            const wasGoverned = step.governed?.model;
            step.governed = undefined;
            delete step.semantic;
            // A REFINED STEP IS RE-SCORED: the corrected query's rows are new
            // rows, and the old prediction columns belonged to the old ones —
            // but unlike a governed compile, scoring can simply run again on
            // what the correction returned. The first live round showed why:
            // the check narrowed a scored step and the reader was left with
            // "the predictions are gone; ask again". So they are scored
            // again, and the note says so; a scoring that fails leaves its
            // own note beside the correction's.
            step.scored = undefined;
            captureResult(step, res);
            results[i] = res;
            step.check = {
              verdict: "refined",
              note:
                (pre ? `${pre.note} ` : "") +
                (c.note || "Corrected on self-review.") +
                (wasGoverned
                  ? ` The correction is hand-written SQL, so this step is no longer compiled from ${wasGoverned}.`
                  : ""),
            };
            if (step.score) {
              const correction = step.check;
              await scoreStep(step, res, i);
              // Read through a fresh reference: the narrowing from
              // `step.scored = undefined` above survives the call.
              const rescored = (step as AnalystStep).scored;
              if (rescored) {
                step.check = {
                  verdict: "refined",
                  note: `${correction.note} The corrected rows were scored again with ${rescored.model}.`,
                };
              } else if (step.check && step.check !== correction) {
                step.check = {
                  verdict: "suspect",
                  note: `${correction.note} ${step.check.note}`,
                };
              }
            }
          } catch (e) {
            // The refinement itself failed — keep the original result and
            // surface the concern rather than losing a working answer.
            step.check = {
              verdict: "suspect",
              note:
                `${c.note || "Self-review proposed a correction"} (the proposed correction failed to run — ` +
                `${(e as Error).message} — so the original result above stands.)`,
            };
          }
        } else {
          step.check = pre
            ? {
                verdict: "suspect",
                note: `${pre.note} Self-check: ${c.verdict}${c.note ? ` — ${c.note}` : ""}.`,
              }
            : { verdict: c.verdict, note: c.note };
        }
        step.status = "done";
      }
    } catch {
      // A failed check call must not sink a finished analysis: present the
      // results unchecked and SAY so, never silently pretend they passed.
      turn.steps.forEach((s) => {
        if (s.status === "checking") {
          s.status = "done";
          s.check = { verdict: "suspect", note: "Self-check unavailable for this run." };
        }
      });
    }
    emit();

    // 4. SYNTHESIZE, and chart EVERY step that has something to show
    turn.status = "synthesizing";
    emit();
    const synthPrompt = buildSynthesisPrompt({
      question: args.question,
      approach: turn.approach ?? "",
      prior,
      steps: turn.steps.map((s, i) => ({
        goal: s.goal,
        facts: stepFacts(results[i], s),
        verdict: s.check?.verdict,
        note: s.check?.note,
        error: s.error,
        scored: s.scored ? scoredLabel(s.scored) : undefined,
        forecast: !!s.forecast,
        scoredNotes: s.scored?.notes,
      })),
    });
    const [synth] = await Promise.all([
      ask<unknown>({ ...synthPrompt, model: args.model, maxTokens: ANALYST_TOKENS.synthesis }),
      chartEveryStep({ turn, results, question: args.question, model: args.model, llm: ask }),
    ]);
    const parsed = parseSynthesisReply(synth);
    turn.answer =
      parsed.answer ||
      "The analysis completed but produced no write-up — the step results above stand on their own.";
    if (parsed.followUps.length > 0) turn.followUps = parsed.followUps;
    turn.chartStep = leadChartStep(turn.steps, headline);
    turn.status = "done";
    emit();
    return turn;
  } catch (e) {
    turn.error = (e as Error).message;
    turn.status = "error";
    emit();
    return turn;
  }
}

// ── Editing a step, and rewriting the findings ───────────────────────────
//
// Showing the SQL and refusing to let anyone change it is half a promise.
// An analyst who reads a step, spots the wrong filter, and can only start
// the whole question over is not a partner. So a step's SQL is editable and
// re-runnable ON ITS OWN — and because the findings above were written from
// the OLD numbers, the turn is marked stale until they are rewritten.

/**
 * Re-run one step with the user's SQL. Returns the patched step; the caller
 * decides where it lands. Never mutates its input.
 */
export async function rerunStep(args: {
  step: AnalystStep;
  sql: string;
  execute?: (sql: string) => Promise<QueryResult>;
}): Promise<AnalystStep> {
  const clean = assertSelectOnly(args.sql);
  const run = args.execute ?? (await import("@/lib/sqlEngine")).runQuery;
  const res = await run(clean);
  return {
    ...args.step,
    sql: clean,
    columns: res.columns,
    rows: res.rows.slice(0, ANALYST_ROW_CAP),
    rowCount: res.rows.length,
    edited: true,
    error: undefined,
    status: "done",
    // The previous verdict judged the previous query. Keeping it would let a
    // green "Check passed" vouch for SQL the analyst never saw.
    check: { verdict: "suspect", note: "Edited and re-run by hand — not self-checked." },
    // Same for the chart: it was chosen for the old result's shape.
    chart: undefined,
    // And for the predictions: they belonged to the old rows. A hand-run
    // step is unscored until the question is asked again.
    scored: undefined,
    score: undefined,
  };
}

/** Mark a turn's findings as predating its results (after a step re-run). */
export function withStaleAnswer(turn: AnalystTurn, steps: AnalystStep[]): AnalystTurn {
  return { ...turn, steps, answerStale: true };
}

/**
 * Rewrite the findings from the CURRENT step results, and re-chart the steps
 * whose results changed. This is the same synthesis the loop runs — not a
 * lighter one — so a rewritten answer is worth exactly as much as the first.
 */
export async function resynthesizeTurn(args: {
  turn: AnalystTurn;
  priorTurns: AnalystTurn[];
  model?: string;
  /** Model transport; defaults to the browser session. See LlmJsonFn. */
  llm?: LlmJsonFn;
  onUpdate?: (turn: AnalystTurn) => void;
}): Promise<AnalystTurn> {
  const ask: LlmJsonFn = args.llm ?? llmJson;
  const turn: AnalystTurn = {
    ...args.turn,
    steps: args.turn.steps.map((s) => ({ ...s })),
    status: "synthesizing",
  };
  args.onUpdate?.({ ...turn });
  // The stored trace is the only source here: a step's sample IS what the
  // reader can see, so the write-up is grounded in exactly that.
  const asResult = (s: AnalystStep): QueryResult | null =>
    s.rows && s.columns
      ? {
          columns: s.columns,
          rows: s.rows,
          row_count: s.rowCount ?? s.rows.length,
          total_matched: s.rowCount ?? s.rows.length,
          capped: (s.rowCount ?? 0) > s.rows.length,
          duration_ms: 0,
        }
      : null;
  const results = turn.steps.map(asResult);
  try {
    const prompt = buildSynthesisPrompt({
      question: turn.question,
      approach: turn.approach ?? "",
      prior: priorContext(args.priorTurns),
      steps: turn.steps.map((s, i) => ({
        goal: s.goal,
        facts: stepFacts(results[i], s),
        verdict: s.check?.verdict,
        note: s.check?.note,
        error: s.error,
        scored: s.scored ? scoredLabel(s.scored) : undefined,
        forecast: !!s.forecast,
        scoredNotes: s.scored?.notes,
      })),
    });
    const [synth] = await Promise.all([
      ask<unknown>({ ...prompt, model: args.model, maxTokens: ANALYST_TOKENS.synthesis }),
      chartEveryStep({ turn, results, question: turn.question, model: args.model, llm: ask }),
    ]);
    const parsed = parseSynthesisReply(synth);
    if (parsed.answer) turn.answer = parsed.answer;
    turn.followUps = parsed.followUps.length > 0 ? parsed.followUps : undefined;
    turn.chartStep = leadChartStep(turn.steps, turn.chartStep ?? 0);
    turn.answerStale = false;
    turn.status = "done";
  } catch (e) {
    // The old findings stay, and stay MARKED stale — the failure must not
    // quietly re-bless prose written for different numbers.
    turn.status = "done";
    turn.answerStale = true;
    turn.error = `Could not rewrite the findings: ${(e as Error).message}`;
  }
  args.onUpdate?.({ ...turn });
  return turn;
}
